#include "observed_scene.h"
#include "observed_recovery_features.h"
#include <algorithm>
#include <sstream>
#include <limits>
std::vector<std::vector<double>> readcsv(const std::string&name){std::ifstream f(name);if(!f)throw std::runtime_error("missing "+name);std::string line;std::getline(f,line);std::vector<std::vector<double>> rows;while(std::getline(f,line)){std::replace(line.begin(),line.end(),',',' ');std::istringstream in(line);double v;std::vector<double> a;while(in>>v)a.push_back(v);if(!a.empty())rows.push_back(a);}return rows;}
P::s_t getstate(const std::vector<double>&a){P::s_t s;s.pos[0]=a[1];s.pos[1]=a[2];s.h=a[3];s.V=a[4];s.gamma=a[5];s.sigma=a[6];s.roll=a[7];s.attack=a[8];s.T=a[9];s.d_sigma=0;tf::Quaternion q;q.setRPY(-s.roll,-s.attack-s.gamma,s.sigma);s.q[0]=q.w();s.q[1]=q.x();s.q[2]=q.y();s.q[3]=q.z();return s;}
struct Cand{int id;float cost;P::pr_t command;P::rollout_t path;};
void dump(std::ofstream&f,int scene,int id,int succ,const P::rollout_t&path){float elapsed=0;for(size_t k=0;k<path.states.size();++k){if(k)elapsed+=std::min(0.02f,3.0f-elapsed);const auto&s=path.states[k];f<<scene<<','<<id<<','<<succ<<','<<k<<','<<(succ<0?0:3)+elapsed<<','<<s.pos[0]<<','<<s.pos[1]<<','<<s.h<<','<<s.V<<','<<s.gamma<<','<<s.sigma<<','<<s.roll<<','<<s.attack<<','<<s.T<<'\n';}}
int reason(const P&p,const P::s_t&initial,const P::rollout_t&r){if(r.early_rejected){if(r.early_rejection_reason==P::rejection_reason_t::ENVELOPE)return 1;if(r.early_rejection_reason==P::rejection_reason_t::COLLISION)return 2;if(r.early_rejection_reason==P::rejection_reason_t::KNOWN_SPACE)return 3;}if(!r.valid)return 4;if(r.collision)return 2;if(!p.within_recovery_envelope(r))return 1;if(!p.within_known_space(initial,r))return 3;return 0;}
std::pair<int,int> blockers(const sensor_occupancy::Map&m,const P::rollout_t&r){int unknown=0,occupied=0;if(r.states.empty())return {0,0};const auto&v=r.states.back();const auto&u=r.states[r.states.size()>1?r.states.size()-2:0];Pt a{u.pos[0],u.pos[1],u.h},b{v.pos[0],v.pos[1],v.h};const double margin=3,res=m.resolution();for(int x=std::floor((std::min(a.x,b.x)-margin)/res)-1;x<=std::floor((std::max(a.x,b.x)+margin)/res)+1;++x)for(int y=std::floor((std::min(a.y,b.y)-margin)/res)-1;y<=std::floor((std::max(a.y,b.y)+margin)/res)+1;++y)for(int z=std::floor((std::min(a.z,b.z)-margin)/res)-1;z<=std::floor((std::max(a.z,b.z)+margin)/res)+1;++z){sensor_occupancy::Key k{x,y,z};auto c=m.state(k);if(c!=sensor_occupancy::Cell::FREE&&m.intersects_expanded_voxel(a,b,k,margin)){if(c==sensor_occupancy::Cell::UNKNOWN)++unknown;else ++occupied;}}return {unknown,occupied};}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("pair output-directory");std::string out=argv[1];ros::init(argc,argv,"tro_pair",ros::init_options::AnonymousName);std::ofstream paths(out+"/paths.csv"),summary(out+"/candidate_checks.csv"),maps(out+"/map_summary.csv"),commands(out+"/controls.csv");paths<<std::setprecision(17);summary<<std::setprecision(17);maps<<std::setprecision(17);commands<<std::setprecision(17);paths<<"scene,candidate,successor,k,t,x,y,h,V,gamma,heading,roll,attack,thrust\n";summary<<"scene,candidate,cost,rank,successor,verified,work,rejection,unknown_blockers,occupied_blockers\n";maps<<"scene,scans,free_cells,occupied_cells,library,feasible,positive,first_positive,first_negative\n";commands<<"scene,candidate,successor,roll,attack,thrust,duration\n";
int sceneindex=0;for(int family:{2,0}){Scene sc=scene(family,0,1201000);const std::string casename="val_"+sc.name+"_m0";ros::NodeHandle nh("/tro_pair/"+casename);cfg(nh,sc,"");P p(nh);p.planning_timer.stop();p.global_target.pos[0]=250;p.global_target.pos[1]=0;p.global_target.h=20;auto rows=readcsv(out+"/"+casename+"_path.csv");auto dirs=directions();for(const auto&a:rows){if(a[0]>.80000001)break;int step=std::lround(a[0]*10);if(step%2==0)scan(p,sc,getstate(a),a[0],dirs);}const auto initial=getstate(rows.at(8));if(std::abs(rows.at(8)[0]-.8)>1e-7)throw std::runtime_error("wrong query");auto start=initial;P::FlagScope scope(p.planning_guard_active,true);std::vector<Cand> cand;auto lib=p.generate_library(initial);for(size_t i=0;i<lib.size();++i){auto path=p.rollout_motion_primitive(initial,lib[i]);float c=p.evaluate_motion_primitive(initial,lib[i],path);if(p.check_primary_feasibility(initial,path)&&std::isfinite(c))cand.push_back({int(i),c,lib[i],path});}
std::stable_sort(cand.begin(),cand.end(),[](const Cand&a,const Cand&b){return a.cost<b.cost;});std::ofstream features(out+"/"+casename+"_rerun.f32",std::ios::binary);int positives=0,firstpos=-1,firstneg=-1;
for(size_t rank=0;rank<cand.size();++rank){const auto&c=cand[rank];P::recovery_candidate_t item;item.terminal=c.path.states.back();item.cost=c.cost;auto f=p.recovery_features(initial,item);f.resize(28);const auto&z=item.terminal;auto obs=observed_recovery::encode(p.sensor_map->map(),z.pos[0],z.pos[1],z.h,z.sigma,z.V,p.recovery_horizon);f.insert(f.end(),obs.begin(),obs.end());auto succ=p.generate_recovery_library(z);assert(succ.size()==15);std::array<float,115>row{};row[0]=4;row[1]=rank+1;row[2]=c.cost;row[11]=c.id;std::copy(f.begin(),f.end(),row.begin()+12);bool found=false;std::vector<P::rollout_t>rolls;
for(size_t j=0;j<succ.size();++j){auto t=p.rollout_motion_primitive(z,succ[j],c.command.t_way,-1,&initial);int why=reason(p,initial,t),work=t.states.size()-1;row[70+3*j]=why==0;row[71+3*j]=work;row[72+3*j]=why;if(!found){row[4]+=work;row[5]+=1;if(why==2)row[6]++;if(why==1)row[7]++;if(why==3)row[8]++;if(why==4)row[9]++;}if(why==0)found=true;auto blocked=why==2?blockers(p.sensor_map->map(),t):std::make_pair(0,0);summary<<sceneindex<<','<<c.id<<','<<c.cost<<','<<rank+1<<','<<j<<','<<(why==0)<<','<<work<<','<<why<<','<<blocked.first<<','<<blocked.second<<'\n';rolls.push_back(std::move(t));}
row[3]=found;row[10]=15;positives+=found;bool firstpositive=found&&firstpos<0;if(firstpositive)firstpos=c.id;if(!found&&firstneg<0)firstneg=c.id;features.write(reinterpret_cast<char*>(row.data()),sizeof(row));if(c.id==69||firstpositive){dump(paths,sceneindex,c.id,-1,c.path);commands<<sceneindex<<','<<c.id<<",-1,"<<c.command.w_roll_c<<','<<c.command.attack_c<<','<<c.command.T_c<<','<<c.command.t_way<<'\n';for(size_t j=0;j<succ.size();++j){dump(paths,sceneindex,c.id,j,rolls[j]);commands<<sceneindex<<','<<c.id<<','<<j<<','<<succ[j].w_roll_c<<','<<succ[j].attack_c<<','<<succ[j].T_c<<','<<succ[j].t_way<<'\n';}}
}
const auto&ms=p.sensor_map->map().stats();maps<<sceneindex<<','<<ms.scans<<','<<ms.free_cells<<','<<ms.occupied_cells<<','<<lib.size()<<','<<cand.size()<<','<<positives<<','<<firstpos<<','<<firstneg<<'\n';std::ofstream cells(out+"/"+casename+"_slice.csv");cells<<"x,y,z,occupancy\n";for(auto kind:{sensor_occupancy::Cell::FREE,sensor_occupancy::Cell::OCCUPIED})for(const auto&v:p.sensor_map->map().snapshot(kind))if(v.z>=18&&v.z<22&&v.x>=-10&&v.x<=135&&std::abs(v.y)<=75)cells<<v.x<<','<<v.y<<','<<v.z<<','<<int(kind)<<'\n';std::cout<<casename<<" feasible="<<cand.size()<<" positive="<<positives<<" firstpos="<<firstpos<<" firstneg="<<firstneg<<std::endl;ros::param::del(nh.getNamespace());++sceneindex;}
ros::shutdown();}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
